import { readFileSync } from "node:fs";
import { basename } from "node:path";

import { type APIRequestContext } from "@playwright/test";

import { expect, sample, test, uniqueName } from "../../fixtures";

// features: review vendors. Rejecting an extraction requires a note and returns the vendor to the member.

async function uploadAll(member: APIRequestContext, vendorId: string): Promise<Record<string, string>> {
  const files: Array<[string, string]> = [
    ["w9", "w9.txt"],
    ["insurance_certificate", "insurance_certificate.txt"],
    ["contract", "contract.txt"],
  ];
  const ids: Record<string, string> = {};
  for (const [kind, file] of files) {
    const filePath = sample(file);
    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: { name: basename(filePath), mimeType: "text/plain", buffer: readFileSync(filePath) },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
    ids[kind] = ((await res.json()) as { id: string }).id;
  }
  return ids;
}

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three extracted documents
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const createRes = await member.post("/api/vendors", {
    data: { name: uniqueName("Rev06 Vendor"), category: "services", contact_email: "ops@rev06.example" },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendorId = ((await createRes.json()) as { id: string }).id;

  const documentIds = await uploadAll(member, vendorId);

  // Extraction runs in the background; wait until every document is extracted before submitting.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendorId}/documents`);
        const docs = (await res.json()) as Array<{ status: string }>;
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submitRes = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submitRes.status(), await submitRes.text()).toBe(200);
  expect(((await submitRes.json()) as { status: string }).status).toBe("in_review");

  const extractionRes = await reviewer.get(`/api/documents/${documentIds.w9}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extractionId = ((await extractionRes.json()) as { id: string }).id;

  // Act: reject the W-9 extraction without a note
  const noNoteRes = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject" },
  });

  // Assert: refused, and the vendor is still in review
  expect(noNoteRes.status(), await noNoteRes.text()).toBe(422);
  const stillRes = await member.get(`/api/vendors/${vendorId}`);
  expect(stillRes.status(), await stillRes.text()).toBe(200);
  expect(((await stillRes.json()) as { status: string }).status).toBe("in_review");

  // Act: reject the W-9 extraction with a note
  const rejectRes = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });
  expect(rejectRes.status(), await rejectRes.text()).toBe(200);

  // Assert: vendor status is rejected and the audit trail records the rejection
  const vendorRes = await member.get(`/api/vendors/${vendorId}`);
  expect(vendorRes.status(), await vendorRes.text()).toBe(200);
  expect(((await vendorRes.json()) as { status: string }).status).toBe("rejected");

  const auditRes = await reviewer.get(`/api/vendors/${vendorId}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const audit = (await auditRes.json()) as { items: Array<{ action: string }> };
  expect(audit.items.map((e) => e.action)).toContain("extraction.rejected");
});
